function prepareHighSchoolYearOneMatch(options = {}) {
  assertHighSchoolMatchCapabilityAdmission(player);
  if (options.matchContext && typeof MatchContextFoundation === "undefined") throw new Error("Explicit match context requires MatchContextFoundation");
  const targetMatchId = options.matchId || "hs-y1-autumn-exhibition";
  const targetEventId = options.eventId || "high_school_showcase";
  const highSchoolYear = Math.max(1, Math.min(3, Math.floor(Number(options.highSchoolYear) || 1)));
  const opportunityIndex = Math.max(1, Number(options.opportunityIndex) || 1);
  if (player.highSchoolMatch?.id === targetMatchId) {
    const match = player.highSchoolMatch;
    if (options.matchContext) {
      if (!match.matchContext) throw new Error("Existing match has no explicit context; cannot reassign a started match");
      const requested = MatchContextFoundation.normalizeMatchContext({...match.matchContext, ...options.matchContext});
      if (JSON.stringify(requested) !== JSON.stringify(match.matchContext)) throw new Error("Existing match context cannot change");
    }
    if (match.completed || (typeof match.simulationPhase === "string" && match.rosters?.home?.lineup?.length === 9 && match.rosters?.away?.lineup?.length === 9)) {
      match.currentMomentId = getHighSchoolYearOneMomentId(match);
      if (!match.completed && match.currentDomain === "defense" && isInfieldDecisionFamilyPosition(match.developmentPositionOverride || match.position) && match.defensiveSituation?.familyId !== "infield") {
        buildInfieldMeaningfulMoment(match, player);
        match.currentAssignment = getHighSchoolDefensiveSituationText(match);
        setHighSchoolCoachTacticalDirection(match);
      }
      return match;
    }
  }
  const code = ["starter", "rotation", "bench"].includes(player.highSchoolRoleCode) ? player.highSchoolRoleCode : "bench";
  if (highSchoolYear === 1 && !player.highSchoolYearOneStartingRole) player.highSchoolYearOneStartingRole = code;
  const roleAssignments = {
    starter: { lineupStatus: "starter", entryWindowInning: 1, history: `以${player.primaryPosition || "守備"}先發，從開賽起進入守備與打序` },
    rotation: { lineupStatus: "bench", entryWindowInning: 4, history: `本場先從板凳待命，預計在中段代打並接替${player.primaryPosition || "守備"}` },
    bench: { lineupStatus: "bench", entryWindowInning: 5, history: `本場先從板凳觀察，等待中後段代打與短局守備機會` }
  };
  const position = player.primaryPosition || "內野手";
  const requestedDevelopmentPosition = opportunityIndex === 1 && infieldPositions.includes(pendingHighSchoolMatchPositionOverride)
    ? pendingHighSchoolMatchPositionOverride : "";
  if (requestedDevelopmentPosition && !isDevelopmentTestPositionLegalForThrowingHand(requestedDevelopmentPosition, player.throws, player.age)) {
    throw new Error(getDevelopmentTestPositionLegalityMessage(requestedDevelopmentPosition, player.throws));
  }
  const developmentPositionOverride = requestedDevelopmentPosition;
  const suppliedOpportunity = options.opportunityDecision || null;
  const simulationSeed = suppliedOpportunity
    ? createHighSchoolMatchSimulationSeedFromIdentity(suppliedOpportunity.decisionId || suppliedOpportunity.matchId)
    : createHighSchoolMatchSimulationSeed();
  const directStartForced = highSchoolYear === 1 && opportunityIndex === 1
    && Array.isArray(player.flags) && player.flags.includes("direct_start_history");
  const opportunityDecision = suppliedOpportunity || createHighSchoolPlayingTimeOpportunity({
    matchId: targetMatchId,
    actualRole: code,
    requestedPosition: developmentPositionOverride || position,
    directStartForced,
    opportunityIndex,
    opportunityPhase: options.opportunityPhase || "autumn-exhibition",
    highSchoolYear
  });
  if ((suppliedOpportunity || opportunityIndex > 1) && (!opportunityDecision || opportunityDecision.matchId !== targetMatchId)) {
    throw new Error(`高中第 ${highSchoolYear} 年第 ${opportunityIndex} 次實戰必須直接消費相同 match identity 的既有 Opportunity。`);
  }
  if (opportunityDecision && typeof HighSchoolCompetitionReassessment !== "undefined") {
    player.highSchoolOpportunityHistory = HighSchoolCompetitionReassessment.recordOpportunity(player.highSchoolOpportunityHistory, {
      opportunity: opportunityDecision,
      opportunityIndex,
      roleAtCreation: code
    });
  }
  const plannedAppearance = opportunityDecision?.plannedUsage?.appearanceType || (code === "starter" ? "start" : "lateGameAppearance");
  const starts = plannedAppearance === "start";
  const roleAssignment = opportunityDecision
    ? {
      lineupStatus: starts ? "starter" : "bench",
      entryWindowInning: starts ? 1 : Math.max(5, Number(opportunityDecision.plannedUsage.entryInning) || 5),
      history: getHighSchoolPlayingTimeAssignmentText(opportunityDecision)
    }
    : roleAssignments[code];
  const assignedPosition = opportunityDecision?.assignedPosition || developmentPositionOverride || position;
  const developmentTestCapabilityOverride = developmentPositionOverride
    ? createDevelopmentMatchPositionTestCapabilityOverride(developmentPositionOverride, player) : null;
  const selectedSchoolRoster = materializeSelectedHighSchoolRoster(player, {
    rosterRole: starts ? "starter" : "bench",
    playerPosition: assignedPosition
  });
  const rosters = createHighSchoolMatchSimulationRoster(
    starts ? "starter" : code === "starter" ? "bench" : code,
    assignedPosition,
    simulationSeed,
    selectedSchoolRoster,
    options.opponentRosterId || "regional-power-school"
  );
  const matchContext = typeof MatchContextFoundation !== "undefined" ? MatchContextFoundation.createMatchContext({
    matchId: targetMatchId,
    playerTeamId: rosters.home.teamRoster?.teamId || "home",
    opponentTeamId: rosters.away.teamRoster?.teamId || "away",
    matchOrigin: options.matchType === "final-competition" ? "officialCompetition" : "developmentMatch",
    legacyFallback: !options.matchContext,
    ...options.matchContext
  }) : null;
  if (matchContext && (matchContext.matchId !== targetMatchId || matchContext.playerTeamId !== (rosters.home.teamRoster?.teamId || "home") || matchContext.opponentTeamId !== (rosters.away.teamRoster?.teamId || "away"))) throw new Error("Match context / roster identity mismatch");
  if (matchContext && MatchContextFoundation.isPlayerAway(matchContext)) [rosters.home, rosters.away] = [rosters.away, rosters.home];
  const playerSide = matchContext ? MatchContextFoundation.playerSide(matchContext) : "home";
  const playerLineupSlot = rosters[playerSide].lineup.findIndex(item => item.id === "player");
  const resolvedCompetitionRules = typeof CompetitionRules !== "undefined"
    ? CompetitionRules.resolveMatchCompetitionRules(matchContext)
    : null;
  const regulationInnings = resolvedCompetitionRules?.rules.regulationInnings
    || Math.max(1, Number(player.highSchoolMatch?.regulationInnings) || 7);
  player.highSchoolMatch = {
    id: targetMatchId,
    matchContext,
    ...(resolvedCompetitionRules ? {
      ruleSetId: resolvedCompetitionRules.ruleSetId,
      rules: resolvedCompetitionRules.rules,
      ruleSetWarning: resolvedCompetitionRules.warning
    } : {}),
    ...(options.scheduleCompetitionRefs || {}),
    eventId: targetEventId,
    matchType: options.matchType || "autumn-exhibition",
    highSchoolYear,
    opportunityIndex,
    opponent: options.opponent || "高橋所屬的地區強校",
    inning: 1,
    half: "上",
    outs: 0,
    scores: { home: 0, away: 0 },
    runners: [null, null, null],
    role: code,
    position,
    assignment: roleAssignment.history,
    matchEntryHistory: `${roleAssignment.history}；${formatHandedness(player.bats, player.throws)}`,
    currentAssignment: starts ? (playerSide === "home" ? "比賽從一局上開始；先完成守備，再等待打序輪到你。" : "比賽從一局上開始；依打序完成進攻，再進入守備。") : "比賽從一局上開始；你在板凳觀察，但場上每個打席都會完整進行。",
    offenseTeam: "away",
    defenseTeam: "home",
    currentBatter: rosters.away.lineup[0]?.id || "",
    battingOrderIndex: { home: 0, away: 0 },
    tiebreakHalfInitialization: null,
    halfInningResolved: false,
    simulationPhase: "full_match_flow",
    simulationCursor: 0,
    simulationSeed,
    simulationLog: [],
    presentedEventCursor: 0,
    scoreboardRevealHalfIndex: 0,
    regulationInnings,
    lineScore: { home: [], away: [] },
    gameRecord: null,
    rosters,
    playerLineupStatus: roleAssignment.lineupStatus,
    playerLineupSlot,
    playerFieldingAssignment: starts ? assignedPosition : "",
    playerEntryWindowInning: roleAssignment.entryWindowInning,
    playerEntryCompleted: starts,
    performanceEvidence: {},
    matchExperience: null,
    gameExposureState: opportunityDecision && typeof PlayingTimeGameExposure !== "undefined"
      ? PlayingTimeGameExposure.createGameExposureState(opportunityDecision) : null,
    developmentFullMatchStart: pendingHighSchoolFullMatchTest,
    playerRunnerLocation: -1,
    momentIndex: 0,
    currentMomentId: highSchoolYearOneMomentIds[0],
    currentDomain: "flow",
    coachTacticalDirection: { domain: "", intent: "", riskPreference: "", priority: "", sourceCoachId: "", presentationStyle: "" },
    coachTacticalContextSignature: "",
    opponentTacticalTruth: { code: "", targetRunnerId: "" },
    ballContext: { type: "", family: "", pace: "", label: "", detail: "", timeWindow: "" },
    positionDecisionFamily: "", currentFieldingPosition: starts && (developmentPositionOverride || opportunityDecision?.positionFallbackApplied) ? assignedPosition : "", developmentPositionOverride,
    developmentTestCapabilityOverride, defensiveSituation: {},
    matchDecisionDensityState: createHighSchoolMatchDecisionDensityState(),
    pitcherRuntimeState: null,
    pitcherSequencingDebugTrace: [],
    pitcherObservableHistory: [],
    pitcherTacticalSequenceHistory: [],
    pitcherTacticalDebugTrace: [],
    batterAnticipationState: null,
    prePitchPlanningState: null,
    offensivePlateAppearanceState: null,
    pendingOffensiveOpportunity: null,
    offensivePlayerAgencyState: null,
    offensiveTacticalActionState: null,
    offensiveBuntPAState: null,
    buntBallInPlayState: null,
    pendingDefensiveResumeState: null,
    lastDefensiveResolution: { resultCode: "", tier: "", decisionQuality: "", executionQuality: "", primaryCause: "", secondaryCause: "", causeExplanation: "" },
    pendingHalfInningTermination: null,
    catcherDecisionState: null,
    catcherReassessmentTrigger: null,
    completedMoments: [],
    playerContribution: { strong: 0, mixed: 0, failure: 0, runsCreated: 0, runsScored: 0, hits: 0, walks: 0, outsCreated: 0, errors: 0 },
    previousMomentDecision: "",
    previousMomentOutcome: "",
    passage: "",
    opponentAdjustment: "",
    coachInstruction: starts ? "先跟著比賽完成每個守備與打席。" : "先讀完整比賽流；被叫到時直接接進當下局面。",
    decision: "",
    outcomeTier: "",
    outcome: "",
    consequence: "",
    coachReaction: "現任教練確認你的第一個場上任務。",
    teamReaction: "休息區把下一段比賽交到你手上。",
    performanceSummary: "",
    teamResult: "",
    settled: false,
    pendingGameSettlement: "",
    eventSettlementApplied: false,
    developmentPresentationCompleted: false,
    completed: false
  };
  ensureHighSchoolPitcherRuntimeState(player.highSchoolMatch);
  if (isHighSchoolMatchOpportunityDebugMode()) ensureHighSchoolMatchOpportunityTrace(player.highSchoolMatch);
  setHighSchoolCoachTacticalDirection(player.highSchoolMatch);
  recordHighSchoolMatchSimulationEvent(player.highSchoolMatch, {
    type: "matchEntry", inning: 1, half: "上",
    outs: 0, runners: player.highSchoolMatch.runners,
    scores: player.highSchoolMatch.scores,
    assignment: player.highSchoolMatch.matchEntryHistory
  });
  pendingHighSchoolMatchPositionOverride = "";
  pendingHighSchoolFullMatchTest = false;
  player.highSchoolRoleContext.assignment = roleAssignment.history;
  return player.highSchoolMatch;
}

// Match opportunities are school-to-school fixtures, separate from PlayingTimeGameExposure decisions.

function prepareCurrentHighSchoolYearOneMatch() {
  if (getCurrentEventId() === "critical_tournament" && isCanonicalHighSchoolYearThreeRoute()) return prepareHighSchoolYearThreeMatch();
  if (getCurrentEventId() === "high_school_year_two_autumn_stage" && isHighSchoolYearOneMatchEventId("high_school_year_two_autumn_stage")) {
    return prepareHighSchoolYearTwoAutumnMatch();
  }
  if (getCurrentEventId() === "high_school_year_two_spring_game" && isHighSchoolYearOneMatchEventId("high_school_year_two_spring_game")) {
    return prepareHighSchoolYearTwoEvaluationMatch();
  }
  return getCurrentEventId() === "high_school_followup_evaluation"
    ? prepareHighSchoolFollowupEvaluationMatch()
    : prepareHighSchoolYearOneMatch();
}

function resolveHighSchoolYearOneMatch(decision, expectedMomentId = "", randomSource = Math.random) {
  const match = prepareCurrentHighSchoolYearOneMatch();
  if (match.simulationPhase === "offensive_agency_ready") {
    const agencySelection = decision === "agencyManual" ? "manual" : decision === "agencySimulate" ? "simulate" : "";
    return agencySelection ? chooseHighSchoolOffensiveAgency(agencySelection, expectedMomentId || match.offensivePlayerAgencyState?.momentId) : false;
  }
  const activeSituation = typeof MatchSituationLifecycle !== "undefined"
    ? MatchSituationLifecycle.normalizeSituation(match.activeSituation) : null;
  if (activeSituation?.type === "plateDecision") {
    if (expectedMomentId && expectedMomentId !== getHighSchoolYearOneMomentId(match)) return false;
    const legalRoute = activeSituation.legalRoutes.find(route => route.routeId === decision || route.matchDecision === decision);
    if (!legalRoute) return false;
    const resolvedPitch = resolveHighSchoolPlateDecisionPitch(match, legalRoute.routeId);
    if (!resolvedPitch) return false;
    const pitchText = formatHighSchoolPlateDecisionPitchResult(resolvedPitch.event);
    if (!resolvedPitch.plateAppearanceCompleted) return pitchText;
    const selectedChoice = resolvedPitch.selectedOffensiveChoice || match.plateDecisionState?.selectedOffensiveChoice;
    const completed = match.momentIndex === 0
      ? advanceHighSchoolYearOneAfterMomentOne(match, selectedChoice, null)
      : resolveHighSchoolYearOneFinalMoment(match, selectedChoice, null);
    return completed ? `${pitchText} ${match.completedMoments.at(-1).outcome}。${match.completedMoments.at(-1).consequence}` : false;
  }
  if (activeSituation?.type === "runnerTagUpDecision") {
    if (expectedMomentId && expectedMomentId !== match.currentMomentId) return false;
    const legalRoute = activeSituation.legalRoutes.find(route => route.routeId === decision || route.matchDecision === decision);
    if (!legalRoute) return false;
    const closed = resolveHighSchoolRunnerTagUpDecision(match, legalRoute.routeId, { randomSource });
    const outcome = match.lastClosedSituationSummary?.outcome || closed?.resolution?.reason || "";
    return outcome === "safeHome" ? "你衝回本壘得分。" : outcome === "taggedOutAtHome" ? "你在本壘前被觸殺出局。" : "你留在三壘。";
  }
  const currentMomentId = getHighSchoolYearOneMomentId(match);
  const legalChoices = getHighSchoolYearOneMatchMomentChoices(match);
  const legalChoice = legalChoices.find(choice => choice.matchDecision === decision);
  const expectedPhase = `moment_${match.momentIndex + 1}_ready`;
  if (match.completed || match.simulationPhase !== expectedPhase || !currentMomentId || (expectedMomentId && expectedMomentId !== currentMomentId) || !legalChoice) return false;
  if (match.completedMoments.some(moment => moment.id === currentMomentId)) return false;
  if (match.momentIndex === 0) {
    if (!advanceHighSchoolYearOneAfterMomentOne(match, legalChoice, null)) return false;
    return `${match.completedMoments.at(-1).outcome}。${match.completedMoments.at(-1).consequence}`;
  }
  if (match.momentIndex === 1) {
    beginGroundBallSituationDecision(match, decision);
    const defensiveResolution = resolveHighSchoolDefensivePlay(match, decision, randomSource);
    recordGroundBallSituationResolution(match, defensiveResolution);
    const tier = defensiveResolution?.tier || "failure";
    advanceHighSchoolYearOneAfterMomentTwo(match, decision, tier, defensiveResolution);
    return `${match.completedMoments.at(-1).outcome}。${match.completedMoments.at(-1).consequence}`;
  }
  return resolveHighSchoolYearOneFinalMoment(match, legalChoice, null);
}

function advanceHighSchoolMatchPlaybackStep(match = player.highSchoolMatch) {
  if (!match || match.completed) return false;
  if (match.activeSituation?.type === "groundBallDefensiveDecision" && match.activeSituation.lifecycleState === "resolved") {
    return resumeResolvedHighSchoolGroundBallSettlement(match);
  }
  if (!isHighSchoolMatchPlaybackPhase(match)) return false;
  const activeSituation = typeof MatchSituationLifecycle !== "undefined"
    ? MatchSituationLifecycle.normalizeSituation(match.activeSituation) : null;
  if (activeSituation && !MatchSituationLifecycle.canResumeSimulation(activeSituation)) return "decision";
  const pendingEvent = advanceHighSchoolPresentationCursor(match);
  if (pendingEvent) return getHighSchoolPlaybackResultForPresentedEvent(pendingEvent);
  if (match.pendingGameSettlement) {
    finishHighSchoolMatchBySimulation(match);
    return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match)) || "gameEnd";
  }
  if (needsHighSchoolScoreboardReveal(match)) {
    match.scoreboardRevealHalfIndex = getHighSchoolScoreboardRevealHalfIndex(match) + 1;
    const visibleHalf = getHighSchoolHalfInningFromIndex(match.scoreboardRevealHalfIndex);
    match.passage = `${visibleHalf.inning}局${visibleHalf.half}已在記分板上展開；比分只顯示目前播放到的進度。`;
    return "scoreboardReveal";
  }
  const target = match.simulationPhase === "full_match_flow" ? "firstOffense"
    : match.simulationPhase === "moment_1_resolved" ? "defense"
    : match.simulationPhase === "moment_2_resolved" ? "finalOffense" : "finish";
  const startIndex = getHighSchoolPresentedEventCursor(match);
  const scoresBefore = { ...match.scores };
  const playerStartedOnBase = match.playerRunnerLocation >= 0;
  const startingInning = match.inning;
  const startingHalf = match.half;

  if (isHighSchoolMatchWalkOff(match)) {
    recordHighSchoolMatchSimulationEvent(match, {
      type: "walkOff", inning: match.inning, half: match.half, scores: match.scores
    });
    match.pendingGameSettlement = "walkOff";
    advanceHighSchoolPresentationCursor(match);
    return "walkOff";
  }

  if (match.outs >= 3 && shouldEndHighSchoolMatchAfterHalf(match, startingInning, startingHalf)) {
    finishHighSchoolMatchAtCompletedHalf(match, startingInning, startingHalf);
    match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
    return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
  }
  if (match.outs >= 3) {
    endHighSchoolMatchHalfInning(match);
    const runs = (match.scores.home - scoresBefore.home) + (match.scores.away - scoresBefore.away);
    match.currentAssignment = `${startingInning}局${startingHalf}已結束；接著進入${match.inning}局${match.half}。`;
    match.passage = `${startingInning}局${startingHalf}完成，這個半局產生 ${runs} 分。記分板保留先前所有局數，下一個半局接著開始。`;
    return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
  }

  if (shouldEnterHighSchoolMatchPlayer(match)) {
    enterHighSchoolMatchPlayer(match);
    match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
    return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
  }

  const batter = getHighSchoolMatchLineupBatter(match, match.offenseTeam);
  if (batter?.id === "player") {
    const agencyChoices = buildOffensiveDecisionChoices(match).filter(choice => isOffensiveDecisionChoiceLegal(choice, match));
    const agencyClassification = classifyHighSchoolOffensiveOpportunity(match, agencyChoices);
    const agencyDensity = evaluateHighSchoolOffensiveDecisionDensity(match, agencyClassification);
    const agency = evaluateHighSchoolOffensivePlayerAgency(match, agencyClassification);
    if (agency.lateGamePlayerAgency) {
      const routeTarget = target === "firstOffense" && shouldCreateHighSchoolFirstOffensiveMoment(match) ? "firstOffense"
        : target === "finalOffense" && shouldReachHighSchoolFinalOffensiveMoment(match) ? "finalOffense" : "classified";
      prepareHighSchoolOffensiveAgencyChoice(match, agencyClassification, agencyDensity, { routeTarget });
      match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
      return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
    }
  }
  const defensiveOpportunity = beginHighSchoolMatchDefensiveOpportunity(match, batter, target);
  if (target === "firstOffense" && shouldCreateHighSchoolFirstOffensiveMoment(match)) {
    prepareHighSchoolFirstOffensiveMomentFromSimulation(match);
    match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
    return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
  }
  const activeFieldingPosition = match.developmentPositionOverride || match.playerFieldingAssignment || match.currentFieldingPosition || match.position;
  const defensiveOpportunityPhase = target === "defense" || activeFieldingPosition === "一壘手"
    || (["二壘手", "游擊手", "三壘手", "一壘手"].includes(activeFieldingPosition) && ["finalOffense", "finish"].includes(target));
  const defensiveResponsibilityReached = defensiveOpportunityPhase && shouldReachHighSchoolDefensiveMoment(match);
  if (defensiveOpportunity) defensiveOpportunity.responsibilityCheck = defensiveResponsibilityReached;
  if (defensiveResponsibilityReached) {
    const defensiveEvent = prepareHighSchoolDefensiveMomentFromSimulation(match, { opportunityTraceId: defensiveOpportunity?.opportunityId || "",
      incomingContinuation: createHighSchoolIncomingContinuationAdmission(match, batter) });
    if (defensiveEvent) {
      match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
      return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
    }
  }
  if (target === "finalOffense" && shouldReachHighSchoolFinalOffensiveMoment(match)) {
    prepareHighSchoolFinalOffensiveMomentFromSimulation(match);
    match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
    return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
  }
  let offensiveRoutineOpportunity = null;
  if (batter?.id === "player") {
    const choices = buildOffensiveDecisionChoices(match).filter(choice => isOffensiveDecisionChoiceLegal(choice, match));
    const classification = classifyHighSchoolOffensiveOpportunity(match, choices);
    const density = evaluateHighSchoolOffensiveDecisionDensity(match, classification);
    if (density.allowed) {
      applyHighSchoolOffensiveDecisionDensity(match, classification, density, true);
      prepareHighSchoolMeaningfulOffensiveMomentFromSimulation(match, classification, density);
      match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
      return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
    }
    applyHighSchoolOffensiveDecisionDensity(match, classification, density, false);
    offensiveRoutineOpportunity = recordHighSchoolMatchOffensiveOpportunity(match, "routine", choices, classification, density);
  }
  const simulationLogLengthBeforePA = match.simulationLog.length;
  const result = batter ? resolveSimulatedHighSchoolPlateAppearance(match, null, { allowPlayer: batter.id === "player" }) : false;
  if (!result) return false;
  const plateAppearanceEvent = match.simulationLog.slice(simulationLogLengthBeforePA).find(event => event.type === "plateAppearance") || null;
  finalizeHighSchoolMatchDefensiveOpportunity(match, defensiveOpportunity, plateAppearanceEvent, plateAppearanceEvent?.result || "ordinary-pa");
  if (offensiveRoutineOpportunity) {
    offensiveRoutineOpportunity.result = plateAppearanceEvent?.result || "";
    offensiveRoutineOpportunity.simulationLogIndex = Number.isFinite(Number(plateAppearanceEvent?.sequence)) ? Number(plateAppearanceEvent.sequence) : match.simulationLog.length - 1;
  }
  if (isHighSchoolMatchWalkOff(match)) {
    recordHighSchoolMatchSimulationEvent(match, {
      type: "walkOff", inning: match.inning, half: match.half, scores: match.scores
    });
    match.pendingGameSettlement = "walkOff";
  }
  const event = advanceHighSchoolPresentationCursor(match);
  match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
  return getHighSchoolPlaybackResultForPresentedEvent(event);
}

function createHighSchoolPlayingTimeOpportunity(options = {}) {
  if (typeof PlayingTimeGameExposure === "undefined") return null;
  const requestedPosition = options.requestedPosition || player.primaryPosition || "內野手";
  const school = getHighSchoolPlayingTimeSchoolContext(player);
  const readinessSnapshot = createHighSchoolOpportunityReadinessSnapshot(requestedPosition, player);
  const opportunityIndex = Math.max(1, Number(options.opportunityIndex) || 1);
  const schoolYearIdentity = player.schoolInvitationState?.selectedSchoolYearRosterIdentity?.identity
    || `${school.schoolId}|legacy-high-school-year-one`;
  const highSchoolYear = Math.max(1, Math.min(3, Math.floor(Number(options.highSchoolYear) || 1)));
  const yearPhase = highSchoolYear === 1 ? "high-school-year-one" : `high-school-year-${highSchoolYear}`;
  const opportunityPhase = options.opportunityPhase || (opportunityIndex === 1 ? "autumn-exhibition" : "post-autumn-evaluation");
  const resolved = PlayingTimeGameExposure.resolveStartingOpportunity({
    matchId: options.matchId,
    readinessSnapshot,
    opportunitySeed: [player.capabilityState?.settlementId || player.capabilityState?.version || "capability", schoolYearIdentity, yearPhase, opportunityPhase, opportunityIndex, options.matchId || "match"].join("|"),
    actualRole: options.actualRole,
    projectedRole: school.projectedRole,
    playingTimeEnvironment: school.playingTimeEnvironment,
    competitionDepth: school.competitionDepth,
    positionNeed: school.positionNeed,
    coachUsageStyle: school.coachStyle,
    evaluationTrend: options.evaluationTrend,
    previousActualExposure: options.previousActualExposure,
    coachTrust: options.includeDynamicReadiness ? player.relationships?.coachTrust : undefined,
    health: options.includeDynamicReadiness ? player.body : undefined,
    stableVariationSeed: options.stableVariationSeed,
    directStartForced: options.directStartForced === true,
    gameContext: { gameType: "highSchoolExhibition", inning: 0, expectedGameImportance: "regular", importance: "regular", leverage: "normal", scoreMargin: 0 }
  });
  if (!options.preserveDecisionId) return resolved;
  return Object.freeze({
    ...cloneSchoolInvitationValue(resolved),
    decisionId: options.preserveDecisionId,
    opportunitySeed: options.preserveOpportunitySeed || resolved.opportunitySeed
  });
}

function createHighSchoolMatchSimulationSeed(randomSource = Math.random) {
  if (Number(pendingHighSchoolMatchSimulationSeed) > 0) {
    const injectedSeed = Math.max(1, Math.floor(Number(pendingHighSchoolMatchSimulationSeed)));
    pendingHighSchoolMatchSimulationSeed = 0;
    return injectedSeed;
  }
  const sample = Number(randomSource());
  return Math.max(1, Math.floor((Number.isFinite(sample) ? sample : 0.5) * 999983));
}

function createHighSchoolMatchSimulationSeedFromIdentity(identity) {
  const text = String(identity || "hs-y1-match");
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return Math.max(1, hash >>> 0);
}

function getHighSchoolYearOneMatchEventId(match = player.highSchoolMatch) {
  if (isHighSchoolYearOneMatchEventId(match?.eventId)) return match.eventId;
  return match?.id === "hs-y1-followup-evaluation-2" ? "high_school_followup_evaluation" : "high_school_showcase";
}

function getHighSchoolScheduleExecutionContext() {
  const school = player.schoolInvitationState;
  const careerYear = Number(player.highSchoolYearTransitionState?.currentHighSchoolYear) || 1;
  const phases = {high_school_showcase:"autumn-exhibition", high_school_followup_evaluation:"post-autumn-evaluation",
    high_school_year_two_spring_game:"year-two-spring-evaluation", high_school_year_two_autumn_stage:"year-two-autumn-evaluation",
    critical_tournament:"final-competition"};
  const seasonPhase = phases[getCurrentEventId()] || player.highSchoolNextOpportunity?.phase;
  if (!school?.generationSeed || !school.selectedSchoolId || !seasonPhase) throw new Error("Schedule requires admitted career and current match phase");
  return {careerId:school.generationSeed, careerYear, seasonPhase, playerSchoolId:school.selectedSchoolId,
    schoolIds:[school.selectedSchoolId, ...(school.invitations || []).map(item => item.schoolId),
      ...(player.competitionFoundation?.teams || []).filter(item => item.teamType === "school").map(item => item.teamId),
      "regional-power-school", "hs-y2-spring-regional-opponent", "hs-y2-autumn-regional-opponent", "hs-y3-final-regional-opponent"],
    // Reference the existing mandatory career stage, not a second tournament calendar.
    mandatorySlots:careerYear === 3 ? [{careerYear:3,seasonPhase:"final-competition",sequence:1,sourceId:"hs-y3-final-competition-1"}] : []};
}

function launchHighSchoolScheduleEntry(scheduleEntryId, options) {
  assertHighSchoolMatchCapabilityAdmission(player);
  const state = player.highSchoolSchedule;
  const requestedEntry = state?.entries.find(item => item.scheduleEntryId === scheduleEntryId);
  if (!requestedEntry || !["scheduled", "inProgress"].includes(requestedEntry.status)) throw new Error("Schedule entry cannot launch");
  const context = getHighSchoolScheduleExecutionContext();
  const entry = HighSchoolScheduleOpportunity.assertCanLaunch(state,scheduleEntryId,context,player.highSchoolMatch);
  if (entry.status === "inProgress") return player.highSchoolMatch;
  const matchId = options.matchId;
  if (player.highSchoolMatch?.id === matchId || [1,2,3].some(year => {
    const key = ["", "highSchoolYearOneMatchHistory", "highSchoolYearTwoMatchHistory", "highSchoolYearThreeMatchHistory"][year];
    return (player[key] || []).some(item => item.matchId === matchId);
  })) throw new Error("Schedule cannot reuse an existing match identity");
  const matchContext = HighSchoolScheduleOpportunity.deriveMatchContextInput(state,scheduleEntryId,matchId);
  const scheduleCompetitionRefs = getHighSchoolScheduleCompetitionRefs(state.opportunities.find(item => item.opportunityId === entry.opportunityId));
  MatchContextFoundation.createMatchContext(matchContext);
  const match = prepareHighSchoolYearOneMatch({...options, highSchoolYear:entry.careerYear,
    opportunityPhase:entry.seasonPhase, opponentRosterId:entry.opponentSchoolId, matchContext, scheduleCompetitionRefs});
  HighSchoolScheduleOpportunity.markScheduleStarted(state,scheduleEntryId,match);
  return match;
}

function prepareHighSchoolFollowupEvaluationMatch() {
  const opportunity = player.highSchoolNextOpportunity;
  if (!opportunity || opportunity.matchId !== "hs-y1-followup-evaluation-2" || Number(opportunity.opportunityIndex) !== 2) {
    throw new Error("第二次隊內實戰評估缺少既有 Opportunity N+1。");
  }
  const options = {
    matchId: opportunity.matchId,
    eventId: "high_school_followup_evaluation",
    matchType: "evaluation-practice",
    opponent: "受邀協助評估的地區校隊",
    opportunityIndex: 2,
    opportunityPhase: "post-autumn-evaluation",
    opportunityDecision: opportunity
  };
  // Older embedded runtimes without the optional module retain their direct path.
  if (typeof HighSchoolScheduleOpportunity === "undefined") return prepareHighSchoolYearOneMatch(options);
  if (player.highSchoolMatch?.id === opportunity.matchId) return player.highSchoolMatch;
  const context = getHighSchoolScheduleExecutionContext();
  const selection = typeof HighSchoolOpportunitySelection !== "undefined" ? deriveHighSchoolOpportunitySelection() : null;
  const candidate = typeof HighSchoolMatchOpportunityGeneration !== "undefined"
    ? (selection ? selection.selectedCandidates : deriveHighSchoolMatchOpportunityCandidates().eligible).find(item => item.opportunityType === "developmentMatchOpportunity" && item.source.sourceId === opportunity.matchId) : null;
  const alreadyOffered = player.highSchoolSchedule?.opportunities.find(item => item.source.sourceId === opportunity.matchId && item.careerYear === 1 && item.opportunityType === "developmentMatchOpportunity");
  if (typeof HighSchoolMatchOpportunityGeneration !== "undefined" && !candidate && !alreadyOffered) throw new Error("No eligible development match candidate");
  const selectedMaterialization = !alreadyOffered && selection && candidate ? materializeHighSchoolSelectedOpportunities(selection) : null;
  if (selectedMaterialization?.diagnostics.length) throw new Error("Development selection stale at materialization");
  const matchOpportunity = alreadyOffered || (candidate ? (selectedMaterialization ? selectedMaterialization.materialized[0] : materializeHighSchoolMatchOpportunityCandidate(candidate)) : offerHighSchoolMatchOpportunity({opportunityType:"developmentMatchOpportunity",
    source:{type:"developmentSchedule",sourceId:opportunity.matchId}, sequence:2,
    opponentSchoolId:"regional-power-school", provenance:{reasonCode:"existing-followup-evaluation"},
    // Preserve the established fixture assignment explicitly; MatchContext validates it.
    plannedContext:{homeTeamId:context.playerSchoolId,awayTeamId:"regional-power-school",assignmentSource:"developmentSchedule"}}));
  // This existing mandatory career evaluation is accepted by its current entry point.
  if (matchOpportunity.status === "offered") HighSchoolScheduleOpportunity.setOpportunityStatus(player.highSchoolSchedule,matchOpportunity.opportunityId,"accepted");
  const entry = HighSchoolScheduleOpportunity.scheduleOpportunity(player.highSchoolSchedule,matchOpportunity.opportunityId,context);
  return launchHighSchoolScheduleEntry(entry.scheduleEntryId,options);
}

function completeHighSchoolEntry(options = {}) {
  const state = player?.schoolInvitationState;
  const invitationValidation = validateSchoolInvitationSet(state);
  if (!invitationValidation.ok) {
    showNotice("高中邀請資料不完整，暫時不能進入高中主篇。", "error");
    return false;
  }
  const directStartBypass = state.compatibilityMode === "direct-start-bypass";
  if (!directStartBypass && state.selectionFinalized !== true) {
    showNotice("請先確認一間高中，再進入高中主篇。", "warning");
    return false;
  }
  if (!directStartBypass && !state.selectedSchoolRoster) {
    materializeSelectedHighSchoolRoster(player, { rosterRole: "bench" });
  }
  if (player.chapter === "青棒" && Number(player.age) === 16) return true;
  const schoolContext = getSelectedHighSchoolContext(player);
  applyChapterBreather();
  player.chapter = "青棒";
  player.age = 16;
  player.highSchoolStep = 0;
  player.highSchoolPositionPreference = player.primaryPosition || "";
  player.highSchoolRoleCode = "";
  player.highSchoolCompetitionEvaluation = null;
  player.highSchoolOpportunityHistory = [];
  player.highSchoolNextOpportunity = null;
  player.highSchoolYearOneStartingRole = "";
  player.highSchoolYearOneMatchHistory = [];
  player.highSchoolYearOneComplete = false;
  player.highSchoolMatch = createInitialPlayer().highSchoolMatch;
  player.highSchoolAzheEcho = createInitialPlayer().highSchoolAzheEcho;
  player.highSchoolRivalContext = createInitialPlayer().highSchoolRivalContext;
  const schoolName = schoolContext?.schoolName || state.legacyExistingSchool?.schoolName || player.highSchoolRoute;
  showNotice(`你進入${schoolName}，高中棒球正式開始。`, "success");
  showCurrentEvent();
  return true;
}

function getCurrentEventId() {
  if (player.completed) return "slice_complete";
  if (player.forcedEventId) return player.forcedEventId;
  if (player.chapter === "二十二歲職涯小結") return "development_result";
  if (player.chapter === "發展期") {
    if (
      typeof CareerDevelopmentRuntimeResolver !== "object" ||
      typeof CareerDevelopmentRuntimeResolver.resolveDevelopmentRuntime !== "function"
    ) return null;
    const runtimeResult = CareerDevelopmentRuntimeResolver.resolveDevelopmentRuntime(player);
    return runtimeResult.resolved ? runtimeResult.eventId : null;
  }
  if (player.chapter === "生涯轉換期小結") return "transition_result";
  if (player.chapter === "生涯轉換期") {
    if (
      typeof CareerTransitionRuntimeResolver !== "object" ||
      typeof CareerTransitionRuntimeResolver.resolveTransitionRuntime !== "function"
    ) return null;
    const runtimeResult = CareerTransitionRuntimeResolver.resolveTransitionRuntime(player);
    return runtimeResult.resolved ? runtimeResult.eventId : null;
  }
  if (player.chapter === "青棒生涯出口") return "critical_year_result";
  if (player.chapter === "青棒關鍵年") {
    const sequence = ["critical_offseason", "critical_tournament", "critical_public_attention", "critical_injury", "critical_scout_interview", "critical_family", "critical_farewell", "critical_exit_choice"];
    return sequence[player.criticalYearStep] || "critical_year_result";
  }
  if (player.chapter === "青棒第一年小結") return "high_school_result";
  if (player.chapter === "青棒第二年小結") return "high_school_year_two_result";
  if (player.chapter === "青棒第二年") {
    const sequence = ["high_school_year_two_roster_reset", "high_school_year_two_role_test", "high_school_year_two_spring_game", "high_school_year_two_depth_chart", "high_school_year_two_body_load", "high_school_year_two_team_responsibility", "high_school_year_two_autumn_stage", "high_school_year_two_senior_plan"];
    return sequence[player.highSchoolYearTwoStep] || "high_school_year_two_result";
  }
  if (player.chapter === "青棒") {
    const sequence = ["high_school_intro", "high_school_load", "high_school_life", "high_school_role", "high_school_long_bench", "high_school_showcase", "high_school_call_home", "high_school_followup_evaluation", "high_school_role_reassessment_feedback", "high_school_scout_feedback"];
    return sequence[player.highSchoolStep] || "high_school_result";
  }
  if (player.chapter === "青少棒階段小結") return "junior_season_result";
  if (player.chapter === "青少棒分化") {
    const sequence = ["junior_consequence", "junior_coach_preference", "junior_senior", "junior_starting_job", "junior_academics", "junior_tournament", "junior_after_loss", "takahashi_school_question", "yamamoto_recommendation", "junior_school_choice"];
    return sequence[player.juniorSeasonStep] || "junior_season_result";
  }
  if (player.chapter === "青少棒開場小結") return "junior_result";
  if (player.chapter === "青少棒") {
    const sequence = ["junior_intro", "junior_repetition", "junior_growth_test", "junior_position_change", "junior_azhe_cover", "junior_takahashi_failure", "junior_coach_disagreement", "junior_home_night", "junior_friend_exit", "junior_pain"];
    return sequence[player.juniorStep] || "junior_result";
  }
  if (player.chapter === "位置競爭小結") return "competition_result";
  if (player.chapter === "位置競爭") {
    if (player.competitionStep === 0) return "competition_intro";
    if (player.competitionStep === 1) return "competition_training_week";
    if (player.competitionStep === 2) {
      if (player.impression.coach.immature >= 5) return "echo_coach_immature";
      if (player.impression.coach.dependable >= 5 && player.impression.coach.leader >= 3) return "echo_coach_leadership";
      if (player.impression.takahashi.respect >= 5) return "echo_rival_respect";
      if (player.relationships.coachTrust >= 6) return "echo_coach";
      if (player.relationships.teammateBond >= 5) return "echo_teammate";
      if (player.relationships.rivalCompetition >= 5) return "echo_rival";
      return "echo_solo";
    }
    if (player.competitionStep === 3) {
      if (player.impression.azhe.feelsDistance >= 5 || player.relationships.teammateBond <= 1) return "azhe_bond_low";
      if (player.impression.azhe.trusts >= 5 || player.relationships.teammateBond >= 6) return "azhe_bond_high";
      return "azhe_bond_mid";
    }
    if (player.competitionStep === 4) return "competition_role_talk";
    return player.seasonPosition === "捕手" ? "competition_catcher_test" : "competition_position_test";
  }
  if (player.chapter === "少棒第一季小結") return "youth_season_result";
  if (player.chapter === "少棒第一季") {
    const positionPlay = { "內野手": "youth_match_grounder", "外野手": "youth_match_outfield", "捕手": "youth_match_catcher", "投手": "youth_match_pitcher" }[player.seasonPosition] || "youth_match_grounder";
    const sequence = ["youth_season_intro", "youth_position_trial", "youth_teammate", "youth_bench", "youth_match_entry", positionPlay, "youth_match_mistake", "youth_match_after"];
    return sequence[player.seasonStep] || "youth_season_result";
  }
  if (player.chapter === "少棒入門小結") return "chapter2_result";
  if (player.chapter === "少棒入門") {
    const sequence = ["chapter2_intro", "chapter2_day1_training", "chapter2_team_breath", "chapter2_day2_correction", "chapter2_batting_intro", "chapter2_day3_test"];
    return sequence[player.chapter2Step] || "chapter2_result";
  }
  if (player.ending) return "ending";
  if (player.phase === "night") return "night";
  return `day${player.day}_${player.phase}`;
}

function getEvent(eventId) {
  if (typeof isCanonicalHighSchoolYearThreeRoute === "function" && isCanonicalHighSchoolYearThreeRoute()
    && (eventId.startsWith("critical_") || eventId === "transition_draft_day")) {
    const finale = getHighSchoolYearThreeEvent(eventId);
    if (finale) return finale;
  }
  if (eventId === "night") return getNightEvent();
  return chapterOneEvents[eventId] || chapterTwoEvents[eventId] || youthSeasonEvents[eventId] || positionCompetitionEvents[eventId] || juniorBaseballEvents[eventId] || juniorSeasonEvents[eventId] || highSchoolEvents[eventId] || highSchoolYearTwoEvents[eventId] || criticalYearEvents[eventId] || careerTransitionEvents[eventId] || pacingEvents[eventId] || developmentEvents[eventId] || null;
}

function deriveMatchContextInput(state, scheduleEntryId, matchId) {
  const entry = state.entries.find(item => item.scheduleEntryId === scheduleEntryId);
  check(entry, "unknown entry");
  const opportunity = state.opportunities.find(item => item.opportunityId === entry.opportunityId);
  check(opportunity, "orphan entry"); id(matchId);
  check(!entry.matchId || entry.matchId === matchId, "entry already linked to another match");
  return {...copy(entry.plannedContext), matchId, matchOrigin:entry.matchOrigin,
    playerTeamId:opportunity.playerSchoolId, opponentTeamId:entry.opponentSchoolId,
    seasonId:identity("hs-season",[opportunity.careerId,entry.careerYear]), scheduleEntryId,
    provenance:{...copy(opportunity.provenance), source:opportunity.source.type, sourceId:opportunity.source.sourceId,
      opportunityId:opportunity.opportunityId, scheduleEntryId, opportunitySource:copy(opportunity.source), competitionRefs:copy(opportunity.competitionRefs)}};
}

function markScheduleStarted(state, scheduleEntryId, match) {
  const entry = state.entries.find(item => item.scheduleEntryId === scheduleEntryId);
  check(entry && entry.status === "scheduled" && match.matchContext?.scheduleEntryId === scheduleEntryId, "invalid start link");
  check(!state.entries.some(item => item.matchId === match.id), "match already linked");
  entry.matchId = id(match.id); entry.status = "inProgress"; return entry;
}

